}"},{"rank":2,"score":27.6971,"file_path":"api/checkpoint/interfaces.go","start_line":93,"end_line":106,"focus_line":93,"snippet_start_line":93,"snippet_end_line":106,"symbol_start_line":93,"symbol_end_line":106,"language":"Go","kind":"function","symbol_id":"local/cli:Go:api/checkpoint/interfaces.go:function:ReadCheckpoint","symbol_name":"ReadCheckpoint","qualified_name":"ReadCheckpoint","signature":"func ReadCheckpoint(ctx context.Context, reader CheckpointReader, checkpointID id.CheckpointID) (*CheckpointSummary, error)","signals":["graph:calls","graph:incoming","graph:callers","complete-symbol"],"snippet":"func ReadCheckpoint(ctx context.Context, reader CheckpointReader, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
